Title.BackgroundTransparency = 1
Title.Text = "vviolette script"
Title.TextColor3 = Color3.fromRGB(255, 255, 255)
Title.TextScaled = true
Title.Font = Enum.Font.GothamBold
Title.Parent = MainFrame

local Author = Instance.new("TextLabel")
Author.Size = UDim2.new(1, 0, 0, 20)
Author.Position = UDim2.new(0, 0, 0, 40)
Author.BackgroundTransparency = 1
Author.Text = "by Zigafon775"
Author.TextColor3 = Color3.fromRGB(180, 180, 180)
Author.TextScaled = true
Author.Font = Enum.Font.Gotham
Author.Parent = MainFrame

-- Цветовые темы
local themes = {
    ["ПРИЯТНЫЙ"] = {main = Color3.fromRGB(255, 105, 180), accent = Color3.fromRGB(255, 182, 193)},
    ["КРУТОЙ"]   = {main = Color3.fromRGB(0, 255, 255), accent = Color3.fromRGB(0, 170, 255)},
    ["КРАСИВЫЙ"] = {main = Color3.fromRGB(138, 43, 226), accent = Color3.fromRGB(186, 85, 211)}
}

local currentTheme = "ПРИЯТНЫЙ"

local function applyTheme(themeName)
    currentTheme = themeName
    local t = themes[themeName]
    
    MainFrame.BackgroundColor3 = Color3.fromRGB(25, 25, 35)
    
    -- Анимация смены цвета
    TweenService:Create(MainFrame, TweenInfo.new(0.4, Enum.EasingStyle.Quint), 
    {BackgroundColor3 = t.main:lerp(Color3.fromRGB(20,20,25), 0.7)}):Play()
end

-- Кнопки тем
local yOffset = 70
for name, _ in pairs(themes) do
    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(0.9, 0, 0, 35)
    btn.Position = UDim2.new(0.05, 0, 0, yOffset)
    btn.BackgroundColor3 = Color3.fromRGB(40, 40, 50)
    btn.Text = name
    btn.TextColor3 = Color3.fromRGB(255, 255, 255)
    btn.TextScaled = true
    btn.Font = Enum.Font.GothamSemibold
    btn.Parent = MainFrame
    
    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 8)
    corner.Parent = btn
    
    btn.MouseButton1Click:Connect(function()
        applyTheme(name)
    end)
    
    yOffset += 45
end

-- Запуск оригинального скрипта
local success, err = pcall(function()
    loadstring(OriginalScript)()
end)

if not success then
    warn("Ошибка загрузки vviolette: " .. err)
end

print("✅ vviolette script успешно загружен | Zigafon775")

-- Draggable
local dragging, dragInput, dragStart, startPos

MainFrame.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragging = true
        dragStart = input.Position
        startPos = MainFrame.Position
    end
end)

MainFrame.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 then
        dragging = false
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
        local delta = input.Position - dragStart
        MainFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end
end)
